#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

Node *new_node(int value) {
    Node *p = (Node *)malloc(sizeof(Node));
    if (p == NULL) {
        return NULL;
    }
    p->value = value;
    p->left = NULL;
    p->right = NULL;
    return p;
}

Node *insert(Node *root, int value) {
    if (root == NULL) {
        return new_node(value);
    }
    if (value < root->value) {
        root->left = insert(root->left, value);
    } else if (value > root->value) {
        root->right = insert(root->right, value);
    }
    return root;
}

void inorder(Node *root) {
    if (root == NULL) {
        return;
    }
    inorder(root->left);
    printf("%d ", root->value);
    inorder(root->right);
}

int count_nodes(Node *root) {
    if (root == NULL) {
        return 0;
    }
    return 1 + count_nodes(root->left) + count_nodes(root->right);
}

int tree_height(Node *root) {
    if (root == NULL) {
        return 0;
    }
    int lh = tree_height(root->left);
    int rh = tree_height(root->right);
    return 1 + (lh > rh ? lh : rh);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    Node *root = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) {
            return 1;
        }
        root = insert(root, v);
    }

    printf("挂了 %d 个接头\n", count_nodes(root));
    printf("这架架子有 %d 层高\n", tree_height(root));
    printf("中序：");
    inorder(root);
    printf("\n");
    return 0;
}

explanationTemplate:
这两招都是「**自己 + 两只叉 → 合成一个答案**」的路子喵，而且开头都得先问一句「是不是空叉」：**空叉算 0** —— 这两招的答案都是「个数」，一只接头都没有当然是 0。

**① 数接头。** 自己算 1 个，再把左边那只叉里的接头数、右边那只叉里的接头数各要一份，三份加起来：

```text
return 1 + count_nodes(root->left) + count_nodes(root->right);
```

**② 数层高。** 这个比数接头绕一点：自己这一层当然要算，但底下那两只叉**不用加起来，只要高的那一个** —— 一架架子有多高，取决于**最长的那条路**走了几层。所以先分别问两只叉各自多高，取大的那个，再加自己这一层：

```text
int lh = tree_height(root->left);
int rh = tree_height(root->right);
return 1 + (lh > rh ? lh : rh);
```

注意 `1 +` 的位置和那个「取大的」：本喵见过有猫把两只叉的高度**加起来**，那样数的其实不是层高，而是「整架架子一共分了多少岔」。

本喵给你留一句分头记：**一人加两只叉，加起来；一层看最长那条路，加一。**
